import json

# Load CoachForce data
with open('/root/DATA/products/CoachForce.json', 'r') as f:
    coachforce = json.load(f)

# Search for Market Research Report with author/reviewer info
documents = coachforce.get('documents', [])
for i, doc in enumerate(documents):
    if doc.get('type') == 'Market Research Report' or doc.get('document_type') == 'Market Research Report':
        # Print the keys to understand the structure
        print(f"Document {i} keys: {doc.keys()}")
        if 'author' in doc:
            print(f"Author: {doc.get('author')}")
        if 'authors' in doc:
            print(f"Authors: {doc.get('authors')}")
        if 'reviewer' in doc:
            print(f"Reviewer: {doc.get('reviewer')}")
        if 'reviewers' in doc:
            print(f"Reviewers: {doc.get('reviewers')}")
        if 'author_id' in doc:
            print(f"Author ID: {doc.get('author_id')}")
        if 'created_by' in doc:
            print(f"Created by: {doc.get('created_by')}")
        print("---")
EOF

